function UIBattlingDiscoverCardSkillCell:Start()
    UIEventProxy.Create(self.Btn_Click.gameObject).onPointerClick = function()
        local roleView = UIBattlingTools.GetRoleViewData(self.roleId)
        local isDead = roleView:IsDead()
        if isDead then return end -- 死亡角色技能卡不能发现
        if self.skillCardData.cardBehavior == Constants.CardBehavior.Search then return end --类型发现不能发现
        local skillCardPosData = self.posData
        local data2Logic = { pos = skillCardPosData,  params = { roleId = self.roleId, skillIndex = self.skillIndex, star = self.star } }
        -- print("->DiscoverCard_Data2Logic", table.dump(checkTable(data2Logic)))
        if self.callBack then
            self.callBack(data2Logic)
        end
    end
end

