function UIBattlingDiscoverCardSkillCell:SetSkillCard(skillCardId, star, skillIndex)
    local skillData = { skillId = skillCardId, star = star, skillLv = 1, skillIndex = skillIndex, roleId = self.roleId }
    local skillCardNodeLB = GetLuaBehaviour(UIBattlingTools.ReloadPoolObjGO(Constants.UIBattlingObjPoolPrefabs.PATH_SKILLCARD_GO, self.Root_SkillCard), Constants.UIBattlingLuaTablePath.SkillCardsNodePath)
    local skillCard = skillCardNodeLB.Env
    skillCard:SetSkillCardInfo(skillData)
    skillCard:RemoveListener()
    skillCard:SetSkillCardCG2Show()
    skillCard:SetEventReceiverEnableState(false)
    if self.skillCardData.cardBehavior == Constants.CardBehavior.Search then
        local disableNode = UIBattlingTools.ReloadPoolObjGO(Constants.UIBattlingObjPoolPrefabs.Unreachable, skillCard.ParticalRoot.gameObject)
    end
    if UIBattlingCtrlMgr:GetInstance():CheckSkillCardLockStatus(skillCard) then
        skillCard:SkillCardLocked()
    end
    --TODO 测试
    xTry(function()
        -- print("->DataTest:", UIBattlingDataMgr:GetSkillCardRoleIdWithIndexId(skillCardId))
    end)
end

